package practice.e;

// TODO: make this a JPA entity on table "product": UNIQUE constraint on sku (name it), an index on (category, name).
// TODO: Long id generated by the database (IDENTITY); sku not null length 20; name not null length 80; category not null length 40;
//       priceCents not null; active not null and TRUE for a new product. Add a protected no-arg constructor for JPA.
public class Product {
    private Long id;
    private String sku;
    private String name;
    private String category;
    private long priceCents;
    private boolean active = true;

    public Product(String sku, String name, String category, long priceCents) {
        this.sku = sku;
        this.name = name;
        this.category = category;
        this.priceCents = priceCents;
    }

    public Long getId() { return id; }
    public String getSku() { return sku; }
    public String getName() { return name; }
    public String getCategory() { return category; }
    public long getPriceCents() { return priceCents; }
    public boolean isActive() { return active; }
}
